{
	AttackType type;
	CalcResult result;
	/** Indexed by EquipmentSlot ordinal; null entries are empty slots. Null if nothing could attack. */
	Optimizer.Candidate[] gear;
	long combinationsTried;
	int itemsConsidered;
	int itemsAfterPruning;
