package com.slayerbis.calc;

import com.slayerbis.data.AttackType;
import com.slayerbis.data.EquipmentSlot;
import com.slayerbis.data.GameData;
import com.slayerbis.data.GearItem;
import com.slayerbis.data.Monster;
import com.slayerbis.data.TaskMonsterResolver;
import com.google.gson.Gson;
import org.junit.BeforeClass;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Offline checks of the DPS maths against known OSRS reference values. No game client involved.
 */
public class DpsCalculatorTest
{
	private static GameData data;
	private static Monster abyssalDemon;

	@BeforeClass
	public static void load() throws Exception
	{
		data = GameData.load(new Gson());
		abyssalDemon = new TaskMonsterResolver(data).fromName("Abyssal demons");
	}

	static PlayerSetup maxed(boolean onTask)
	{
		return PlayerSetup.builder().attack(99).strength(99).ranged(99).magic(99).hitpoints(99)
			.onSlayerTask(onTask).blowpipeDartStrength(35).build();
	}

	static GearItem item(String name)
	{
		GearItem item = data.findItem(name);
		assertNotNull("missing item " + name, item);
		return item;
	}

	private static GearItem[] gear(String... names)
	{
		GearItem[] gear = new GearItem[EquipmentSlot.values().length];
		for (String n : names)
		{
			GearItem item = item(n);
			gear[item.getSlot().ordinal()] = item;
		}
		return gear;
	}

	@Test
	public void accuracyFormula()
	{
		assertEquals(1 - 10002.0 / (2 * 20001), DpsCalculator.normalAccuracy(20000, 10000), 1e-12);
		assertEquals(10000.0 / (2 * 20001), DpsCalculator.normalAccuracy(10000, 20000), 1e-12);
	}

	@Test
	public void twistedBowScalingCapsAt250Magic()
	{
		// at the 250 magic cap outside raids: 140% accuracy, 215% damage
		assertEquals(140, DpsCalculator.tbowScaling(100, 250, true));
		assertEquals(215, DpsCalculator.tbowScaling(100, 250, false));
	}

	@Test
	public void whipMaxHitAt99Strength()
	{
		// 99 strength, abyssal whip only, controlled (lash): ((99+8+1) * (82+64) + 320) / 640 = 25
		CalcResult r = new DpsCalculator(maxed(false), abyssalDemon).best(gear("Abyssal whip"), AttackType.SLASH);
		assertTrue(r.getDps() > 0);
		int max = r.getStance() == Stance.CONTROLLED ? 25 : (99 + 8) * (82 + 64) / 640;
		assertEquals(max, r.getMaxHit());
	}

	@Test
	public void poweredStaffMaxHits()
	{
		assertEquals(31, WeaponRules.poweredBaseMaxHit("Trident of the Swamp", 99));
		assertEquals(28, WeaponRules.poweredBaseMaxHit("Trident of the Seas", 99));
		assertEquals(34, WeaponRules.poweredBaseMaxHit("Tumeken's shadow", 99));
		assertEquals(33, WeaponRules.poweredBaseMaxHit("Sanguinesti staff", 99));
	}

	@Test
	public void slayerHelmBoostsMeleeOnTaskOnly()
	{
		GearItem[] withHelm = gear("Abyssal whip", "Slayer helmet (i)");
		double onTask = new DpsCalculator(maxed(true), abyssalDemon).best(withHelm, AttackType.SLASH).getDps();
		double offTask = new DpsCalculator(maxed(false), abyssalDemon).best(withHelm, AttackType.SLASH).getDps();
		assertTrue(onTask > offTask * 1.15);
	}

	@Test
	public void rangedNeedsCompatibleAmmo()
	{
		DpsCalculator calc = new DpsCalculator(maxed(false), abyssalDemon);
		assertEquals(0, calc.best(gear("Magic shortbow"), AttackType.RANGED).getDps(), 0);
		assertEquals(0, calc.best(gear("Magic shortbow", "Dragon arrow"), AttackType.RANGED).getDps(), 0);
		assertTrue(calc.best(gear("Magic shortbow", "Amethyst arrow"), AttackType.RANGED).getDps() > 0);
		// blowpipe needs nothing in the ammo slot
		assertTrue(calc.best(gear("Toxic blowpipe"), AttackType.RANGED).getDps() > 0);
	}

	@Test
	public void flyingMonstersAreImmuneToNonPolearmMelee()
	{
		Monster aviansie = new TaskMonsterResolver(data).fromName("Aviansies");
		assertNotNull(aviansie);
		assertTrue(aviansie.has(Monster.FLYING));
		DpsCalculator calc = new DpsCalculator(maxed(false), aviansie);
		assertEquals(0, calc.best(gear("Abyssal whip"), AttackType.SLASH).getDps(), 0);
	}

	@Test
	public void standardSpellsAutocastFromStaff()
	{
		CalcResult r = new DpsCalculator(maxed(false), abyssalDemon).best(gear("Staff of fire"), AttackType.MAGIC);
		assertNotNull(r.getSpell());
		// the best spell depends on the demon's elemental weakness, but at 99 magic it is always a surge
		assertTrue(r.getSpell().getName().endsWith("Surge"));
		assertTrue(r.getMaxHit() >= 21);
		assertEquals(5, r.getAttackSpeedTicks());
	}
}

package com.slayerbis.calc;

import com.slayerbis.data.AttackType;
import com.slayerbis.data.GameData;
import com.slayerbis.data.GearItem;
import com.slayerbis.data.Monster;
import com.slayerbis.data.TaskMonsterResolver;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertTrue;

/**
 * A worst-case bank: one of every equippable item in the game. Checks the search still finishes.
 */
public class OptimizerPerformanceTest
{
	@Test(timeout = 60_000)
	public void everyItemInTheGame() throws Exception
	{
		GameData data = GameData.load(new Gson());
		Monster target = new TaskMonsterResolver(data).fromName("Abyssal demons");
		List<Optimizer.Candidate> bank = new ArrayList<>();
		for (int id = 0; id < 40_000; id++)
		{
			GearItem item = data.getItem(id);
			if (item != null && item.getId() == id)
			{
				bank.add(new Optimizer.Candidate(item, id));
			}
		}

		Optimizer optimizer = new Optimizer(DpsCalculatorTest.maxed(true), target);
		for (AttackType type : AttackType.values())
		{
			long start = System.nanoTime();
			StyleResult r = optimizer.optimise(bank, type);
			long ms = (System.nanoTime() - start) / 1_000_000;
			System.out.printf("%s: %.3f dps, %d -> %d items, %d combinations, %d ms, stopped early %s%n",
				type, r.getResult().getDps(), r.getItemsConsidered(), r.getItemsAfterPruning(),
				r.getCombinationsTried(), ms, r.isStoppedEarly());
			StringBuilder sb = new StringBuilder();
			for (Optimizer.Candidate c : r.getGear())
			{
				if (c != null)
				{
					sb.append(c.getItem().getName()).append(", ");
				}
			}
			System.out.println("  " + sb);
			assertTrue(r.isValid());
		}
	}
}

package com.slayerbis.calc;

import com.slayerbis.data.AttackType;
import com.slayerbis.data.EquipmentSlot;
import com.slayerbis.data.GameData;
import com.slayerbis.data.GearItem;
import com.slayerbis.data.Monster;
import com.slayerbis.data.TaskMonsterResolver;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.List;
import org.junit.BeforeClass;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Offline checks of pruning, set handling and two-handed weapons using made-up banks.
 */
public class OptimizerTest
{
	private static GameData data;
	private static TaskMonsterResolver resolver;

	@BeforeClass
	public static void load() throws Exception
	{
		data = GameData.load(new Gson());
		resolver = new TaskMonsterResolver(data);
	}

	private static List<Optimizer.Candidate> bank(String... names)
	{
		List<Optimizer.Candidate> out = new ArrayList<>();
		for (String n : names)
		{
			GearItem item = data.findItem(n);
			assertNotNull("missing item " + n, item);
			out.add(new Optimizer.Candidate(item, item.getId()));
		}
		return out;
	}

	private static String nameIn(StyleResult r, EquipmentSlot slot)
	{
		Optimizer.Candidate c = r.getGear()[slot.ordinal()];
		return c == null ? null : c.getItem().getName();
	}

	private static Monster monster(String task)
	{
		Monster m = resolver.fromName(task);
		assertNotNull(m);
		return m;
	}

	@Test
	public void outclassedItemsAreRemoved()
	{
		Optimizer o = new Optimizer(DpsCalculatorTest.maxed(false), monster("Abyssal demons"));
		StyleResult r = o.optimise(bank("Abyssal whip", "Bronze full helm", "Helm of Neitiznot", "Leather boots",
			"Dragon boots"), AttackType.SLASH);
		assertTrue(r.isValid());
		assertEquals("Helm of Neitiznot", nameIn(r, EquipmentSlot.HEAD));
		assertEquals("Dragon boots", nameIn(r, EquipmentSlot.FEET));
	}

	@Test
	public void twoHandedWeaponsNeverUseAShield()
	{
		Optimizer o = new Optimizer(DpsCalculatorTest.maxed(false), monster("Abyssal demons"));
		StyleResult r = o.optimise(bank("Dragon 2h sword", "Dragon defender", "Rune scimitar"), AttackType.SLASH);
		assertTrue(r.isValid());
		Optimizer.Candidate weapon = r.getGear()[EquipmentSlot.WEAPON.ordinal()];
		if (weapon.getItem().isTwoHanded())
		{
			assertNull(nameIn(r, EquipmentSlot.SHIELD));
		}
	}

	@Test
	public void bestOfTwoHandedVersusWeaponAndShield()
	{
		Optimizer o = new Optimizer(DpsCalculatorTest.maxed(false), monster("Abyssal demons"));
		// the whip with a defender beats a dragon 2h sword against a 4-tick, high slash-defence target
		StyleResult r = o.optimise(bank("Dragon 2h sword", "Dragon defender", "Abyssal whip"), AttackType.SLASH);
		assertEquals("Abyssal whip", nameIn(r, EquipmentSlot.WEAPON));
		assertEquals("Dragon defender", nameIn(r, EquipmentSlot.SHIELD));
	}

	@Test
	public void completeSetIsTriedAsOneCandidate()
	{
		Optimizer o = new Optimizer(DpsCalculatorTest.maxed(false), monster("Abyssal demons"));
		StyleResult r = o.optimise(bank("Abyssal whip", "Void melee helm", "Void knight top", "Void knight robe",
			"Void knight gloves", "Helm of Neitiznot"), AttackType.SLASH);
		assertTrue(r.getSetsConsidered().contains("Void Knight (melee)"));
		// void's 10% accuracy and strength beats loose pieces with these few other items
		assertEquals("Void melee helm", nameIn(r, EquipmentSlot.HEAD));
		assertEquals("Void knight top", nameIn(r, EquipmentSlot.BODY));
	}

	@Test
	public void slayerHelmChosenOnTask()
	{
		Optimizer o = new Optimizer(DpsCalculatorTest.maxed(true), monster("Abyssal demons"));
		StyleResult r = o.optimise(bank("Abyssal whip", "Slayer helmet (i)", "Helm of Neitiznot"), AttackType.SLASH);
		assertEquals("Slayer helmet (i)", nameIn(r, EquipmentSlot.HEAD));
	}

	@Test
	public void rangedPicksCompatibleAmmo()
	{
		Optimizer o = new Optimizer(DpsCalculatorTest.maxed(false), monster("Abyssal demons"));
		StyleResult r = o.optimise(bank("Magic shortbow", "Dragon arrow", "Rune arrow", "Bronze arrow"), AttackType.RANGED);
		assertTrue(r.isValid());
		assertEquals("Rune arrow", nameIn(r, EquipmentSlot.AMMO));
	}

	@Test
	public void leafyMonsterNeedsLeafBladedWeapon()
	{
		Optimizer o = new Optimizer(DpsCalculatorTest.maxed(false), monster("Kurask"));
		StyleResult r = o.optimise(bank("Abyssal whip", "Leaf-bladed sword"), AttackType.SLASH);
		assertEquals("Leaf-bladed sword", nameIn(r, EquipmentSlot.WEAPON));
	}

	@Test
	public void noUsableGearGivesNoResult()
	{
		Optimizer o = new Optimizer(DpsCalculatorTest.maxed(false), monster("Abyssal demons"));
		StyleResult r = o.optimise(bank("Helm of Neitiznot"), AttackType.MAGIC);
		assertTrue(!r.isValid());
	}

	@Test
	public void taskNamesResolve()
	{
		assertEquals("Abyssal demon", monster("Abyssal demons").getName());
		assertEquals("Kalphite Soldier", monster("Kalphites").getName());
		assertEquals("Wolf", monster("Wolves").getName());
		assertEquals("Dwarf", monster("Dwarves").getName());
		assertEquals("Hellhound", monster("Hellhounds").getName());
		assertEquals("Steel dragon", monster("Metal dragons").getName());
	}

	@Test
	public void setPieceNamesExistInData()
	{
		for (GearSets set : GearSets.ALL)
		{
			for (List<String> names : set.getPieces().values())
			{
				boolean any = false;
				for (String n : names)
				{
					any |= data.findItem(n) != null;
				}
				assertTrue(set.getName() + " has an unknown piece " + names, any);
			}
		}
	}

	@Test
	public void unchargedVariantsAreNotUsable()
	{
		GearItem charged = null;
		GearItem empty = null;
		for (int id : new int[]{12926, 12924})
		{
			GearItem g = data.getItem(id);
			if ("Charged".equals(g.getVersion()))
			{
				charged = g;
			}
			else
			{
				empty = g;
			}
		}
		assertNotNull(charged);
		assertNotNull(empty);
		assertTrue(charged.isUsable());
		assertTrue(!empty.isUsable());
		// the charged version is offered as the "if charged" alternative
		assertEquals(charged.getId(), data.findUsableVariant(empty).getId());
	}

	@Test
	public void cancelFlagStopsTheSearch()
	{
		java.util.concurrent.atomic.AtomicBoolean cancel = new java.util.concurrent.atomic.AtomicBoolean(true);
		Optimizer o = new Optimizer(DpsCalculatorTest.maxed(false), monster("Abyssal demons"), cancel);
		List<Optimizer.Candidate> everything = new ArrayList<>();
		for (int id = 0; id < 40_000; id++)
		{
			GearItem item = data.getItem(id);
			if (item != null && item.getId() == id && item.isUsable())
			{
				everything.add(new Optimizer.Candidate(item, id));
			}
		}
		try
		{
			o.optimise(everything, AttackType.RANGED);
			org.junit.Assert.fail("expected the search to stop");
		}
		catch (java.util.concurrent.CancellationException expected)
		{
			// stopped at the first check
		}
	}

	@Test
	public void requiredShieldIsAlwaysWornAndRulesOutTwoHanders()
	{
		Optimizer o = new Optimizer(DpsCalculatorTest.maxed(true), monster("Basilisks"));
		java.util.Map<EquipmentSlot, java.util.Set<String>> required = new java.util.EnumMap<>(EquipmentSlot.class);
		required.put(EquipmentSlot.SHIELD, new java.util.HashSet<>(java.util.Arrays.asList("Mirror shield", "V's shield")));
		StyleResult r = o.optimise(bank("Dragon 2h sword", "Abyssal whip", "Dragon defender", "Mirror shield"),
			AttackType.SLASH, required);
		assertEquals("Mirror shield", nameIn(r, EquipmentSlot.SHIELD));
		assertEquals("Abyssal whip", nameIn(r, EquipmentSlot.WEAPON));
	}

	@Test
	public void alternativesUseOtherWeapons()
	{
		Optimizer o = new Optimizer(DpsCalculatorTest.maxed(false), monster("Abyssal demons"));
		// different weapon types, so none is removed as outclassed by another
		StyleResult r = o.optimise(bank("Abyssal whip", "Dragon scimitar", "Dragon battleaxe"), AttackType.SLASH);
		assertEquals(2, r.getAlternatives().size());
		String best = nameIn(r, EquipmentSlot.WEAPON);
		for (StyleResult.Alternative alt : r.getAlternatives())
		{
			assertTrue(!best.equals(alt.getGear()[EquipmentSlot.WEAPON.ordinal()].getItem().getName()));
			assertTrue(alt.getResult().getDps() <= r.getResult().getDps());
		}
	}

	@Test
	public void multiMonsterTasksOfferEveryMonster()
	{
		java.util.Set<String> names = new java.util.HashSet<>();
		for (Monster m : resolver.candidates("Metal dragons"))
		{
			names.add(m.getName());
		}
		assertTrue(names.containsAll(java.util.Arrays.asList("Bronze dragon", "Iron dragon", "Steel dragon",
			"Mithril dragon", "Adamant dragon", "Rune dragon")));
		assertTrue(resolver.candidates("Abyssal demons").size() >= 2);
	}
}

package com.slayerbis.calc;

import com.slayerbis.data.AttackType;
import com.slayerbis.data.EquipmentSlot;
import com.slayerbis.data.GameData;
import com.slayerbis.data.GearItem;
import com.slayerbis.data.Monster;
import com.google.gson.Gson;
import org.junit.BeforeClass;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/**
 * Loadouts whose results were checked by hand against the live OSRS Wiki DPS calculator
 * (https://tools.runescape.wiki/osrs-dps/, version 89c3e25) on 2026-10-19.
 *
 * <p>Calculator settings for every case: all skills 99, no prayers, no potions, the combat style
 * named in the case. "On Slayer task" only matters for the slayer helmet case.
 * Expected values are copied from the calculator's Results table, which rounds DPS to 3 decimal
 * places and accuracy to 2.</p>
 *
 * <p>Monster ids: 415 Abyssal demon (Standard), 7245 Greater demon (Level 100),
 * 8031 Rune dragon, 2516 Ankou (Level 86).</p>
 */
public class WikiReferenceTest
{
	private static final int ABYSSAL_DEMON = 415;
	private static final int GREATER_DEMON_100 = 7245;
	private static final int RUNE_DRAGON = 8031;
	private static final int ANKOU_86 = 2516;

	private static GameData data;

	@BeforeClass
	public static void load() throws Exception
	{
		data = GameData.load(new Gson());
	}

	private static PlayerSetup player(boolean onTask)
	{
		return PlayerSetup.builder().attack(99).strength(99).ranged(99).magic(99).hitpoints(99)
			.onSlayerTask(onTask).blowpipeDartStrength(35).build();
	}

	/**
	 * Calculates one stance directly, so the check does not depend on which stance the optimiser prefers.
	 */
	private static void check(int monsterId, AttackType type, Stance stance, boolean onTask,
		int maxHit, double accuracyPercent, double dps, String... items)
	{
		Monster monster = data.getMonster(monsterId);
		assertNotNull(monster);
		GearItem[] gear = new GearItem[EquipmentSlot.values().length];
		for (String name : items)
		{
			GearItem item = data.findItem(name);
			assertNotNull("missing item " + name, item);
			gear[item.getSlot().ordinal()] = item;
		}
		CalcResult r = new DpsCalculator(player(onTask), monster).single(gear, type, stance);
		String label = String.join(", ", items) + " vs " + monster.displayName() + " (" + stance + ")";
		assertEquals(label + ": max hit", maxHit, r.getMaxHit());
		assertEquals(label + ": accuracy", accuracyPercent, r.getAccuracy() * 100, 0.005);
		assertEquals(label + ": dps", dps, r.getDps(), 0.0005);
	}

	@Test
	public void whipOnly()
	{
		check(ABYSSAL_DEMON, AttackType.SLASH, Stance.ACCURATE, false, 24, 62.34, 3.127, "Abyssal whip");
		check(ABYSSAL_DEMON, AttackType.SLASH, Stance.CONTROLLED, false, 25, 61.64, 3.220, "Abyssal whip");
	}

	@Test
	public void midLevelMelee()
	{
		String[] gear = {"Abyssal whip", "Helm of Neitiznot", "Fire cape", "Amulet of fury", "Bandos chestplate",
			"Bandos tassets", "Dragon defender", "Barrows gloves", "Dragon boots", "Berserker ring (i)"};
		check(ABYSSAL_DEMON, AttackType.SLASH, Stance.CONTROLLED, false, 33, 70.98, 4.889, gear);
		check(ABYSSAL_DEMON, AttackType.SLASH, Stance.ACCURATE, false, 33, 71.51, 4.925, gear);
	}

	@Test
	public void slayerHelmetOnTask()
	{
		check(ABYSSAL_DEMON, AttackType.SLASH, Stance.ACCURATE, true, 28, 67.72, 3.960, "Abyssal whip", "Slayer helmet (i)");
		check(ABYSSAL_DEMON, AttackType.SLASH, Stance.CONTROLLED, true, 29, 67.12, 4.064, "Abyssal whip", "Slayer helmet (i)");
	}

	@Test
	public void arclightAgainstDemon()
	{
		check(GREATER_DEMON_100, AttackType.STAB, Stance.CONTROLLED, false, 20, 79.03, 3.309, "Arclight");
	}

	@Test
	public void blowpipeWithDragonDarts()
	{
		check(ABYSSAL_DEMON, AttackType.RANGED, Stance.RAPID, false, 23, 76.35, 7.343,
			"Toxic blowpipe", "Masori mask (f)", "Masori body (f)", "Masori chaps (f)", "Necklace of anguish",
			"Ava's assembler", "Zaryte vambraces", "Pegasian boots", "Venator ring");
	}

	@Test
	public void twistedBowAgainstLowMagic()
	{
		check(ABYSSAL_DEMON, AttackType.RANGED, Stance.RAPID, false, 12, 23.70, 0.480, "Twisted bow", "Dragon arrow");
	}

	@Test
	public void tridentOfTheSwamp()
	{
		check(ABYSSAL_DEMON, AttackType.MAGIC, Stance.ACCURATE, false, 37, 98.56, 7.608,
			"Trident of the Swamp", "Ancestral hat", "Ancestral robe top", "Ancestral robe bottom", "Occult necklace",
			"Tormented bracelet", "Eternal boots", "Magus ring");
	}

	@Test
	public void dragonHunterLanceAgainstDragon()
	{
		check(RUNE_DRAGON, AttackType.STAB, Stance.CONTROLLED, false, 27, 40.33, 2.274, "Dragon hunter lance");
	}

	@Test
	public void salveAgainstUndead()
	{
		check(ANKOU_86, AttackType.SLASH, Stance.ACCURATE, false, 28, 85.22, 4.983, "Abyssal whip", "Salve amulet(ei)");
		check(ANKOU_86, AttackType.SLASH, Stance.CONTROLLED, false, 30, 84.94, 5.320, "Abyssal whip", "Salve amulet(ei)");
	}
}

package com.slayerbis.prep;

import com.google.gson.Gson;
import com.slayerbis.data.AttackType;
import com.slayerbis.data.EquipmentSlot;
import com.slayerbis.data.GameData;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.BeforeClass;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Offline checks of the task preparation data and suggestions. No game client involved.
 */
public class PrepPlannerTest
{
	private static PrepData data;
	private static PrepPlanner planner;
	private static GameData gameData;

	@BeforeClass
	public static void load() throws Exception
	{
		data = PrepData.load(new Gson());
		planner = new PrepPlanner(data);
		gameData = GameData.load(new Gson());
	}

	private static OwnedItems owned(Object... nameQty)
	{
		Map<String, Integer> q = new HashMap<>();
		Map<String, Set<Integer>> ids = new HashMap<>();
		for (int i = 0; i < nameQty.length; i += 2)
		{
			q.put((String) nameQty[i], (Integer) nameQty[i + 1]);
			ids.put((String) nameQty[i], new HashSet<>(Collections.singletonList(1000 + i)));
		}
		return OwnedItems.of(q, ids);
	}

	@Test
	public void namesMatchDosesAndCharges()
	{
		assertTrue(OwnedItems.matches("Prayer potion(3)", "Prayer potion"));
		assertTrue(OwnedItems.matches("Slayer ring (8)", "Slayer ring"));
		assertTrue(OwnedItems.matches("Fungicide spray 10", "Fungicide spray"));
		assertFalse(OwnedItems.matches("Magic potion(4)", "Divine magic potion"));
		assertFalse(OwnedItems.matches("Anti-venom+(4)", "Anti-venom"));
	}

	@Test
	public void basilisksNeedAMirrorShield()
	{
		List<PrepPlan.Requirement> without = planner.requirements("Basilisks", owned(), Collections.emptySet());
		assertEquals(1, without.size());
		assertEquals(EquipmentSlot.SHIELD, without.get(0).getSlot());
		assertFalse(without.get(0).isOwned());

		List<PrepPlan.Requirement> with = planner.requirements("Basilisks", owned("Mirror shield", 1), Collections.emptySet());
		assertTrue(with.get(0).isOwned());

		PrepPlan plan = planner.plan("Basilisks", null, AttackType.SLASH, without, owned(), 4, 1, true);
		assertTrue(plan.getNotes().get(0).contains("Mirror shield"));
	}

	@Test
	public void slayerHelmetCountsByCanonicalName()
	{
		// "Black slayer helmet (i)" reaches the planner as its canonical gear name
		Set<String> gear = new HashSet<>(Collections.singletonList("Slayer helmet (i)"));
		assertTrue(planner.requirements("Aberrant spectres", owned(), gear).get(0).isOwned());
	}

	@Test
	public void superAntifireRemovesTheShieldRequirement()
	{
		assertEquals(1, planner.requirements("Blue dragons", owned(), Collections.emptySet()).size());
		assertEquals(0, planner.requirements("Blue dragons", owned("Extended super antifire(4)", 3),
			Collections.emptySet()).size());
		// wyverns need a shield whatever potions you have
		assertEquals(1, planner.requirements("Skeletal wyverns", owned("Extended super antifire(4)", 3),
			Collections.emptySet()).size());
	}

	@Test
	public void inventoryHasTaskItemsPotionsAndFood()
	{
		OwnedItems bank = owned("Rock hammer", 1, "Super combat potion(4)", 5, "Prayer potion(4)", 20,
			"Shark", 100, "Lobster", 50);
		PrepPlan plan = planner.plan("Gargoyles", "Slayer Tower", AttackType.CRUSH,
			Collections.emptyList(), bank, 4, 1, true);
		assertEquals("Rock hammer", plan.getInventory().get(0).getName());
		assertEquals(PrepPlanner.INVENTORY_SLOTS, plan.getSlotsUsed());
		PrepPlan.InventoryLine food = plan.getInventory().get(plan.getInventory().size() - 1);
		assertEquals("Shark", food.getName());
		assertEquals(PrepPlanner.INVENTORY_SLOTS - 1 - 1 - 4, food.getQuantity());
		assertFalse(plan.getSupplyBankIds().isEmpty());
	}

	@Test
	public void missingTaskItemIsFlagged()
	{
		PrepPlan plan = planner.plan("Gargoyles", null, AttackType.CRUSH, Collections.emptyList(), owned(), 4, 1, true);
		assertTrue(plan.getNotes().stream().anyMatch(n -> n.contains("Rock hammer")));
	}

	@Test
	public void teleportsFollowTheReportedLocation()
	{
		PrepPlan plan = planner.plan("Abyssal demons", "Slayer Tower", AttackType.SLASH, Collections.emptyList(),
			owned("Slayer ring (8)", 1), 0, 0, false);
		assertTrue(plan.getTeleports().stream().allMatch(t -> t.getLocation().equals("Slayer Tower")));
		assertEquals(Boolean.TRUE, plan.getTeleports().get(0).getOwned());
	}

	@Test
	public void requiredItemNamesExistInTheItemData()
	{
		for (Map.Entry<String, PrepData.TaskInfo> task : data.allTasks().entrySet())
		{
			if (task.getValue().required == null)
			{
				continue;
			}
			for (List<String> names : task.getValue().required.values())
			{
				for (String n : names)
				{
					if (!n.equals("Boots of brimstone"))
					{
						assertNotNull(task.getKey() + ": unknown item " + n, gameData.findItem(n));
					}
				}
			}
		}
		for (String n : data.supplies().wyvernShields)
		{
			assertNotNull("unknown shield " + n, gameData.findItem(n));
		}
		for (String n : data.supplies().dragonfireShields)
		{
			assertNotNull("unknown shield " + n, gameData.findItem(n));
		}
	}

	@Test
	public void taskLocationsHaveTeleports()
	{
		for (Map.Entry<String, PrepData.TaskInfo> task : data.allTasks().entrySet())
		{
			if (task.getValue().locations == null)
			{
				continue;
			}
			for (String location : task.getValue().locations)
			{
				assertNotNull(task.getKey() + " lists unknown location " + location, data.locations().get(location));
			}
		}
	}
}
